struct IP{fmpz_poly_struct p[1];IP(){fmpz_poly_init(p);}IP(const IP&a):IP(){fmpz_poly_set(p,a.p);}IP(IP&&a):IP(){fmpz_poly_swap(p,a.p);}IP&operator=(IP a){fmpz_poly_swap(p,a.p);return *this;}~IP(){fmpz_poly_clear(p);}};
struct RM{fmpz_mat_struct m[1];fmpz_t d;RM(int r=0,int c=0){fmpz_mat_init(m,r,c);fmpz_init(d);fmpz_one(d);}RM(const RM&a):RM(fmpz_mat_nrows(a.m),fmpz_mat_ncols(a.m)){fmpz_mat_set(m,a.m);fmpz_set(d,a.d);}RM(RM&&a):RM(){fmpz_mat_swap(m,a.m);fmpz_swap(d,a.d);}RM&operator=(RM a){fmpz_mat_swap(m,a.m);fmpz_swap(d,a.d);return *this;}~RM(){fmpz_mat_clear(m);fmpz_clear(d);}int rows()const{return fmpz_mat_nrows(m);}int cols()const{return fmpz_mat_ncols(m);}void norm(){assert(!fmpz_is_zero(d));if(fmpz_sgn(d)<0){fmpz_neg(d,d);fmpz_mat_neg(m,m);}fmpz_t g;fmpz_init_set(g,d);for(int i=0;i<rows()&&!fmpz_is_one(g);i++)for(int j=0;j<cols();j++)fmpz_gcd(g,g,fmpz_mat_entry(m,i,j));if(!fmpz_is_one(g)){fmpz_divexact(d,d,g);fmpz_mat_scalar_divexact_fmpz(m,m,g);}fmpz_clear(g);}bool zero()const{return fmpz_mat_is_zero(m);}};
RM add(const RM&a,const RM&b){assert(a.rows()==b.rows()&&a.cols()==b.cols());RM c(a.rows(),a.cols()),tmp(a.rows(),a.cols());fmpz_t g,x,y;for(auto p:{g,x,y})fmpz_init(p);fmpz_gcd(g,a.d,b.d);fmpz_divexact(x,b.d,g);fmpz_divexact(y,a.d,g);fmpz_mat_scalar_mul_fmpz(c.m,a.m,x);fmpz_mat_scalar_mul_fmpz(tmp.m,b.m,y);fmpz_mat_add(c.m,c.m,tmp.m);fmpz_mul(c.d,a.d,x);for(auto p:{g,x,y})fmpz_clear(p);c.norm();return c;}
RM neg(RM a){fmpz_mat_neg(a.m,a.m);return a;}
RM mul(const RM&a,const RM&b){assert(a.cols()==b.rows());RM c(a.rows(),b.cols());fmpz_mat_mul(c.m,a.m,b.m);fmpz_mul(c.d,a.d,b.d);c.norm();return c;}
RM sub(const RM&a,const vector<int>&r,const vector<int>&c){RM z(r.size(),c.size());fmpz_set(z.d,a.d);for(int i=0;i<int(r.size());i++)for(int j=0;j<int(c.size());j++)fmpz_set(fmpz_mat_entry(z.m,i,j),fmpz_mat_entry(a.m,r[i],c[j]));z.norm();return z;}
RM solve(const RM&a,const RM&b){assert(a.rows()==a.cols()&&a.rows()==b.rows());RM z(a.cols(),b.cols());if(!fmpz_mat_solve_dixon_den(z.m,z.d,a.m,b.m))throw runtime_error("singular pivot");fmpz_mat_scalar_mul_fmpz(z.m,z.m,a.d);fmpz_mul(z.d,z.d,b.d);z.norm();return z;}
RM embed(const RM&a,const vector<int>&r,int total){RM z(total,a.cols());fmpz_set(z.d,a.d);assert(int(r.size())==a.rows());for(int i=0;i<a.rows();i++)for(int j=0;j<a.cols();j++)fmpz_set(fmpz_mat_entry(z.m,r[i],j),fmpz_mat_entry(a.m,i,j));return z;}
vector<int>range(int n){vector<int>a(n);iota(a.begin(),a.end(),0);return a;}
vector<int>complement(const vector<int>&a,int n){vector<int>v;for(int i=0;i<n;i++)if(find(a.begin(),a.end(),i)==a.end())v.push_back(i);return v;}
RM kernel(const RM&a,const vector<int>&pr,const vector<int>&pc,const vector<int>&fc){RM z=embed(solve(sub(a,pr,pc),neg(sub(a,pr,fc))),pc,a.cols());for(int i=0;i<int(fc.size());i++)fmpz_set(fmpz_mat_entry(z.m,fc[i],i),z.d);assert(mul(a,z).zero());return z;}
int main(int argc,char**argv){assert(argc==5);fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{ifstream in(argv[1]),meta(argv[2]);int nr,n;in>>nr>>n;assert(nr==n);int N=stoi(argv[3]);string prefix=argv[4];vector<map<int,array<IP,3>>>A(n);fmpq_t coeff;fmpq_init(coeff);fmpz_t den,scale,g;for(auto p:{den,scale,g})fmpz_init(p);ulong ex[2];for(int i=0;i<n;i++){int cnt;in>>cnt;map<int,array<Rat,3>>temp;fmpz_one(den);for(int k=0;k<cnt;k++){int j;Rat v;in>>j;readpoly(in,v.n);for(long z=0;z<fmpq_mpoly_length(v.n,ctx);z++){fmpq_mpoly_get_term_exp_ui(ex,v.n,z,ctx);if(ex[1]>2)continue;int t=ex[1];ex[1]=0;fmpq_mpoly_get_term_coeff_fmpq(coeff,v.n,z,ctx);fmpz_lcm(den,den,fmpq_denref(coeff));fmpq_mpoly_push_term_fmpq_ui(temp[j][t].n,coeff,ex,ctx);}}fmpz_zero(g);for(auto&[j,v]:temp)for(int t=0;t<3;t++){fmpq_mpoly_sort_terms(v[t].n,ctx);fmpq_mpoly_combine_like_terms(v[t].n,ctx);for(long k=0;k<fmpq_mpoly_length(v[t].n,ctx);k++){fmpq_mpoly_get_term_exp_ui(ex,v[t].n,k,ctx);fmpq_mpoly_get_term_coeff_fmpq(coeff,v[t].n,k,ctx);fmpz_divexact(scale,den,fmpq_denref(coeff));fmpz_mul(scale,scale,fmpq_numref(coeff));fmpz_poly_set_coeff_fmpz(A[i][j][t].p,ex[0],scale);fmpz_gcd(g,g,scale);}}for(auto&[j,v]:A[i])for(int t=0;t<3;t++)fmpz_poly_scalar_divexact_fmpz(v[t].p,v[t].p,g);}for(auto p:{den,scale,g})fmpz_clear(p);fmpq_clear(coeff);
 int prime,mr,mc,rank,pt;meta>>prime>>mr>>mc>>rank>>pt;assert(mr==n&&mc==n&&rank==255);auto readlist=[&](){int k;meta>>k;vector<int>a(k);for(int&x:a)meta>>x;return a;};vector<int>pr=readlist(),pc=readlist(),fc=readlist(),fr=complement(pr,n),all=range(n),a14=range(14),a4=range(4),one={0};vector<int>r1={1,3,6,7,8,9,10,11,12,13},c1={0,1,2,4,5,6,7,8,9,10},f1={3,11,12,13},rr1={0,2,4,5},r2={0,1,2},c2={0,1,2},f2={3};
 vector<ofstream>out;for(int a=0;a<9;a++){out.emplace_back(prefix+".k"+to_string(a));out.back()<<n<<' '<<N<<" -1\n";}ofstream func(prefix+".functionals");func<<N<<" 3\n";mt19937 rng(20261102);vector<vector<ulong>>weights(3,vector<ulong>(n*9));for(auto&r:weights)for(auto&x:r)x=rng()%32003;fmpz_t e,common,acc,v,sample_scale;for(auto p:{e,common,acc,v,sample_scale})fmpz_init(p);fmpq_t q;fmpq_init(q);auto start=chrono::steady_clock::now();int done=0;
 for(long ev=2;done<N;ev++)try{
  fmpz_set_si(e,ev);array<RM,3>M={RM(n,n),RM(n,n),RM(n,n)};for(int i=0;i<n;i++)for(auto&[j,p]:A[i])for(int t=0;t<3;t++)fmpz_poly_evaluate_fmpz(fmpz_mat_entry(M[t].m,i,j),p[t].p,e);
  RM E=sub(M[0],pr,pc),P0=kernel(M[0],pr,pc,fc);RM P1=embed(solve(E,neg(sub(mul(M[1],P0),pr,a14))),pc,n);RM S1=sub(add(mul(M[1],P0),mul(M[0],P1)),fr,a14);RM K0=kernel(S1,r1,c1,f1);RM Q0=mul(P0,K0),Q1=mul(P1,K0);assert(mul(M[0],Q0).zero());assert(add(mul(M[0],Q1),mul(M[1],Q0)).zero());RM base=add(mul(M[1],Q1),mul(M[2],Q0));RM P2=embed(solve(E,neg(sub(base,pr,a4))),pc,n);RM C=sub(add(base,mul(M[0],P2)),fr,a4);RM K1=embed(solve(sub(S1,r1,c1),neg(sub(C,r1,a4))),c1,14);RM T2=sub(add(C,mul(S1,K1)),rr1,a4);RM z=kernel(T2,r2,c2,f2);RM R0=mul(Q0,z),R1=mul(add(Q1,mul(P0,K1)),z),R2=mul(add(P2,mul(P1,K1)),z);assert(mul(M[0],R0).zero());assert(add(mul(M[0],R1),mul(M[1],R0)).zero());assert(add(add(mul(M[0],R2),mul(M[1],R1)),mul(M[2],R0)).zero());
  vector<RM>V;for(int j=0;j<3;j++)V.push_back(sub(Q0,all,{j}));for(int j=0;j<3;j++)V.push_back(sub(Q1,all,{j}));V.push_back(R0);V.push_back(R1);V.push_back(R2);fmpz_one(common);for(auto&vv:V)fmpz_lcm(common,common,vv.d);for(int a=0;a<9;a++){char*ds=fmpz_get_str(nullptr,10,V[a].d);out[a]<<ev<<' '<<ds;flint_free(ds);for(int i=0;i<n;i++){char*s=fmpz_get_str(nullptr,10,fmpz_mat_entry(V[a].m,i,0));out[a]<<' '<<s;flint_free(s);}out[a]<<'\n';out[a].flush();}func<<ev;for(int k=0;k<3;k++){fmpz_zero(acc);for(int a=0;a<9;a++){fmpz_divexact(sample_scale,common,V[a].d);for(int i=0;i<n;i++){fmpz_mul(v,sample_scale,fmpz_mat_entry(V[a].m,i,0));fmpz_addmul_ui(acc,v,weights[k][i*9+a]);}}fmpz_set(fmpq_numref(q),acc);fmpz_set(fmpq_denref(q),common);fmpq_canonicalise(q);char*s=fmpq_get_str(nullptr,10,q);func<<' '<<s;flint_free(s);}func<<'\n';func.flush();done++;if(done%5==0||done==1)cerr<<"CHAIN_SAMPLE "<<done<<" E "<<ev<<" COMMON_BITS "<<fmpz_bits(common)<<" SEC "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';assert(ev<1500);
 }catch(const runtime_error&ex){cerr<<"SKIP "<<ev<<' '<<ex.what()<<'\n';}
 for(auto p:{e,common,acc,v,sample_scale})fmpz_clear(p);fmpq_clear(q);}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
